SELECT table_name, column_name, data_type
FROM information_schema.columns
ORDER BY table_name, ordinal_position;

SELECT COUNT(DISTINCT order_id) AS orders_last_week, COUNT(*) AS events_last_week
FROM events
WHERE event_name = 'purchase' AND event_ts >= TIMESTAMP '2026-11-16' AND event_ts < TIMESTAMP '2026-11-23';

SELECT COUNT(*) AS german_users
FROM users
WHERE country = 'DE';
